-- ============================================================
-- Seeds the `products` table with the original 17 pieces.
-- Run once, after schema.sql, in the Supabase SQL Editor.
-- ============================================================


-- Keep the id sequence ahead of the explicit ids inserted above,
-- so the next admin-added product gets id 18, not a collision.
select setval(pg_get_serial_sequence('public.products', 'id'), 17, true);
